"""Local FastAPI application. HTML, forms and polling are generated by Python."""
import asyncio
from contextlib import asynccontextmanager
from dataclasses import asdict
import ipaddress
import json
from pathlib import Path
import subprocess
from urllib.parse import urlsplit

from fastapi import FastAPI, HTTPException, Request
from fastapi.responses import FileResponse, HTMLResponse, RedirectResponse
from pydantic import ValidationError

from autoDials import Toolchain
from helpers import discover_masters
from web.jobs import ROOT, JobSpec, JobStore, Settings, contained, source_manifests, validate_spec
from web import ui


def inspect_datasets(paths, settings):
    if not paths:
        return []
    tools = Toolchain(settings.ccp4)
    result = subprocess.run([str(tools.root/'bin/ccp4-python'), str(ROOT/'inspect_hdf.py'), *map(str,paths)],
                            env=tools.env, capture_output=True, text=True, timeout=30, check=True)
    return json.loads(result.stdout)


def create_app(settings=None, start_worker=True, inspector=inspect_datasets):
    settings = settings or Settings.from_env()
    store = JobStore(settings)

    @asynccontextmanager
    async def lifespan(app):
        store.initialize()
        app.state.worker = None
        config = settings.jobs_root/'worker_config.json'
        config.write_text(json.dumps({k: str(v) if isinstance(v, Path) else v for k,v in asdict(settings).items()}, indent=2))
        supervisor = None
        stopping = asyncio.Event()
        log = None
        if start_worker:
            log = (settings.jobs_root/'worker.log').open('a')
            async def supervise():
                while not stopping.is_set():
                    if app.state.worker is None or app.state.worker.poll() is not None:
                        app.state.worker = subprocess.Popen([settings.python,str(ROOT/'web_worker.py'),'--config',str(config)],
                                                            cwd=ROOT,stdout=log,stderr=subprocess.STDOUT)
                    await asyncio.sleep(1)
            supervisor = asyncio.create_task(supervise())
            await asyncio.sleep(0)
        try:
            yield
        finally:
            stopping.set()
            if supervisor:
                supervisor.cancel()
                try:
                    await supervisor
                except asyncio.CancelledError:
                    pass
            worker = app.state.worker
            if worker and worker.poll() is None:
                worker.terminate()
                try:
                    await asyncio.to_thread(worker.wait, 10)
                except subprocess.TimeoutExpired:
                    worker.kill()
                    await asyncio.to_thread(worker.wait)
            if log:
                log.close()

    app = FastAPI(title='Local PyMDA', lifespan=lifespan, docs_url=None, redoc_url=None)
    app.state.settings = settings
    app.state.store = store

    @app.middleware('http')
    async def local_only(request, call_next):
        hostname = urlsplit('//' + request.headers.get('host','')).hostname
        if hostname not in {'localhost','127.0.0.1','::1'}:
            return HTMLResponse(ui.page('Local access', '<h1>This application accepts local requests only.</h1>'), status_code=403)
        if not settings.testing:
            try:
                local = ipaddress.ip_address(request.client.host).is_loopback
            except (ValueError, AttributeError):
                local = False
            if not local:
                return HTMLResponse('Local access only', status_code=403)
        if request.method not in {'GET','HEAD','OPTIONS'}:
            origin = request.headers.get('origin')
            if origin and origin.rstrip('/') != str(request.base_url).rstrip('/'):
                return HTMLResponse('Request must originate from this local application', status_code=403)
        response = await call_next(request)
        response.headers['Content-Security-Policy'] = "default-src 'self'; script-src 'none'; style-src 'self' 'unsafe-inline'; img-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'"
        response.headers['X-Content-Type-Options'] = 'nosniff'
        response.headers['Referrer-Policy'] = 'same-origin'
        return response

    def get_job(identifier):
        job = store.get(identifier)
        if job is None:
            raise HTTPException(404, 'Job not found')
        return job

    def artifact(job, relative, require_file=True):
        root = Path(job['output_dir'])
        try:
            target = contained(root/relative,[root])
        except ValueError:
            raise HTTPException(404,'File not found') from None
        if require_file and not target.is_file():
            raise HTTPException(404,'File not found')
        return target

    def submit(spec):
        try:
            spec = validate_spec(spec, settings)
            if spec.mode in {'process','both'}:
                data = inspector([Path(p) for p in spec.master_files],settings)
                if not data or any(not d['ready'] for d in data):
                    raise ValueError('Selected master files have unreadable metadata or missing companion data')
        except (ValueError,OSError,KeyError,subprocess.SubprocessError) as error:
            raise HTTPException(422,str(error)) from error
        return store.create(spec)

    @app.get('/',response_class=HTMLResponse)
    def home(input_dir: str='', source_dir: str=''):
        input_dir = input_dir or str(settings.input_root)
        source_dir = source_dir or str(settings.output_root)
        data, sources, errors = [], [], []
        try:
            directory = contained(input_dir,[settings.input_root])
            if not directory.is_dir():
                raise ValueError('Input directory does not exist')
            data = inspector(discover_masters(directory),settings)
        except (ValueError,OSError,subprocess.SubprocessError) as error:
            errors.append(str(error))
        try:
            source = contained(source_dir,[settings.output_root,settings.jobs_root])
            for path in source_manifests(source):
                record = json.loads(path.read_text())
                sources.append({'id':path.parent.name,'name':Path(record['config']['master']).name,'frame':record['selected']['last_frame']})
        except (ValueError,OSError,KeyError) as error:
            errors.append(str(error))
        return ui.home(settings,store.list(),input_dir,data,source_dir,sources,'; '.join(errors))

    @app.get('/api/datasets')
    def datasets(input_dir: str=''):
        try:
            directory = contained(input_dir or settings.input_root,[settings.input_root])
            return inspector(discover_masters(directory),settings)
        except (ValueError,OSError,subprocess.SubprocessError) as error:
            raise HTTPException(422,str(error)) from error

    @app.get('/api/jobs')
    def list_jobs():
        return store.list()

    @app.post('/api/jobs',status_code=201)
    def create_job(spec: JobSpec):
        return submit(spec)

    @app.get('/api/jobs/{identifier}')
    def job_status(identifier: str):
        job = get_job(identifier)
        output = Path(job['output_dir'])
        job['statistics'] = ui.load_json(output/'best.json')
        job['comparisons'] = len(ui.load_json(output/'trials.json',[]))
        return job

    @app.post('/jobs')
    async def form_job(request: Request):
        form = await request.form()
        values = dict(form)
        values['master_files'] = form.getlist('master_files')
        values['dataset_ids'] = form.getlist('dataset_ids')
        for name in ('frames','nres','spg','unit_cell','source_dir'):
            if not values.get(name):
                values[name] = None
        if 'resolutions' in values:
            values['resolutions'] = values['resolutions'].replace(',',' ').split()
        values['fix_detector'] = values.get('fix_detector') == 'true'
        try:
            if values.get('mode') == 'assemble' and not values['dataset_ids']:
                raise ValueError('Select at least two processed datasets')
            spec = JobSpec(**values)
            # Metadata and filesystem operations run off the ASGI event loop.
            job = await asyncio.to_thread(submit,spec)
        except (ValueError,ValidationError,HTTPException) as error:
            message = error.detail if isinstance(error,HTTPException) else str(error)
            return HTMLResponse(ui.page('Check parameters','<div class="card"><h1>Check the submitted parameters</h1><p>'+ui.e(message)+'</p><a href="/">Return to the workspace</a></div>'),status_code=422)
        return RedirectResponse('/jobs/'+job['id'],status_code=303)

    @app.get('/jobs/{identifier}',response_class=HTMLResponse)
    def job_page(identifier: str, refresh: str='1', log_file: str='job.stdout.log'):
        job = get_job(identifier)
        artifact(job,log_file,require_file=False)
        if not log_file.endswith('.log'):
            raise HTTPException(404,'Log not found')
        return ui.detail(job,refresh != '0',log_file)

    def change_job(identifier, action):
        get_job(identifier)
        try:
            if action == 'resume':
                validate_spec(JobSpec(**get_job(identifier)['params']),settings)
                store.resume(identifier)
            else:
                store.cancel(identifier)
        except (ValueError,OSError,KeyError) as error:
            raise HTTPException(409,str(error)) from error
        return store.get(identifier)

    @app.post('/api/jobs/{identifier}/cancel')
    def api_cancel(identifier: str):
        return change_job(identifier,'cancel')

    @app.post('/api/jobs/{identifier}/resume')
    def api_resume(identifier: str):
        return change_job(identifier,'resume')

    @app.post('/jobs/{identifier}/cancel')
    def cancel(identifier: str):
        change_job(identifier,'cancel')
        return RedirectResponse('/jobs/'+identifier,status_code=303)

    @app.post('/jobs/{identifier}/resume')
    def resume(identifier: str):
        change_job(identifier,'resume')
        return RedirectResponse('/jobs/'+identifier,status_code=303)

    @app.get('/jobs/{identifier}/file')
    def download(identifier: str, path: str, inline: bool=False):
        target = artifact(get_job(identifier),path)
        inline = inline and target.suffix.lower() in {'.png','.jpg','.jpeg'}
        return FileResponse(target,filename=target.name,content_disposition_type='inline' if inline else 'attachment')

    @app.get('/health')
    def health():
        worker = getattr(app.state,'worker',None)
        return {'status':'ok','worker_running':worker is not None and worker.poll() is None}

    return app


app = create_app()
